edits.new:
MessageDigest hash = MessageDigest.getInstance("SHA-512");
byte[] salt = new byte[16];
(new SecureRandom()).nextBytes(salt);
hash.update(salt);
byte[] hashValue = hash.digest("hash me".getBytes("UTF-8"));
IO.writeLine(IO.toHex(hashValue));
